/* 📖 Grammaticabegrippen: de Franse blokken (cursus Nederlands→Frans). Komt bovenop js/begrippen.js via S.Begrippen.add.
   Elk blok: { n: Franse naam, html, ex, uz (uitzonderingen MÉT reden), table } en optioneel t / k / gen (eigen titel, korte
   omschrijving en algemene uitleg als die van het Spaans afwijkt) en a (extra zoekpatronen voor tikbare woorden). */
(function (S) {
  'use strict';
  if (!S.Begrippen || !S.Begrippen.add) return;
  S.Begrippen.add('fr', {
    zn: { n: 'le nom', gen: 'Een <b>zelfstandig naamwoord</b> is een woord voor een ding, persoon, dier, plaats of idee: <i>tafel, moeder, kat, Parijs, geluk</i>. <b>Test:</b> past er <i>de</i>, <i>het</i> of <i>een</i> voor? Dan is het bijna altijd een zelfstandig naamwoord.',
      html: 'In het Frans is elk zelfstandig naamwoord <b>mannelijk of vrouwelijk</b>, ook dingen en ideeën: <i>le livre</i>, <i>la table</i>. Aan het woord zelf zie je dat vaak niet, dus leer een nieuw woord altijd mét <i>un</i> of <i>une</i>. Handig houvast: woorden op <b>-tion, -té, -ette, -ure</b> zijn bijna altijd vrouwelijk, woorden op <b>-ment, -age, -eau, -isme</b> bijna altijd mannelijk.',
      ex: [['le livre', 'het boek'], ['la ville', 'de stad'], ['un problème', 'een probleem'], ['une solution', 'een oplossing']],
      uz: [['la plage, la page, l’image', 'Woorden op <b>-age</b> zijn mannelijk (<i>le voyage, le fromage</i>), maar <i>la plage, la page, la cage, l’image, la nage, la rage</i> zijn vrouwelijk. <b>Waarom?</b> Bij deze woorden is -age geen achtervoegsel maar een deel van de stam (Latijn <i>pagina, imago</i>), en daar hoorde al een vrouwelijk geslacht bij.']] },
    lidwoord: { n: 'l’article',
      html: 'Het Franse lidwoord past zich aan bij <b>geslacht en getal</b>. Vóór een klinker of stomme h worden <i>le</i> en <i>la</i> <b>l’</b>: <i>l’ami, l’école, l’hôtel</i>. Het Frans heeft ook een <b>delend lidwoord</b> voor "een hoeveelheid van": <i>du pain, de la confiture, de l’eau</i>. In het Nederlands zeg je dan niets: <i>ik eet brood</i>.',
      table: [['', 'mannelijk', 'vrouwelijk', 'meervoud'], ['de / het', 'le (l’)', 'la (l’)', 'les'], ['een', 'un', 'une', 'des'], ['wat / (niets)', 'du (de l’)', 'de la (de l’)', 'des']],
      ex: [['le chat et la maison', 'de kat en het huis'], ['un ami et une amie', 'een vriend en een vriendin'], ['Je mange du pain.', 'Ik eet brood.'], ['J’aime le café.', 'Ik hou van koffie.']],
      uz: [['pas de pain', 'Na een ontkenning worden <i>un, une, du, de la, des</i> allemaal <b>de</b> (of <b>d’</b>): <i>J’ai un chat → Je n’ai pas <b>de</b> chat</i>. <b>Waarom?</b> De hoeveelheid is nul, en na een hoeveelheid (ook <i>beaucoup de, un kilo de</i>) gebruikt het Frans altijd kaal <i>de</i>.'],
        ['au, aux, du, des', '<i>à + le</i> wordt <b>au</b>, <i>à + les</i> wordt <b>aux</b>, <i>de + le</i> wordt <b>du</b>, <i>de + les</i> wordt <b>des</b>. Maar <i>à la</i> en <i>à l’</i> blijven gewoon staan. <b>Waarom?</b> <i>à le</i> en <i>de le</i> werden zo vaak snel na elkaar gezegd dat ze tot één klank versmolten; bij <i>la</i> gebeurde dat niet.']] },
    bn: { n: 'l’adjectif', k: 'Zegt hoe iets of iemand is: groot, mooi, Frans.',
      html: 'Het bijvoeglijk naamwoord staat meestal <b>achter</b> het zelfstandig naamwoord en past zich aan in <b>geslacht en getal</b>: vrouwelijk krijgt meestal <b>-e</b>, meervoud <b>-s</b>: <i>un pull vert, une robe verte, des pulls verts</i>. Die -e hoor je vaak doordat de medeklinker ervoor nu klinkt: <i>petit</i> (pe-tie) → <i>petite</i> (pe-tiet).',
      ex: [['une voiture rouge', 'een rode auto'], ['un film intéressant', 'een interessante film'], ['Elles sont contentes.', 'Ze (vrouwen) zijn blij.']],
      uz: [['petit, grand, beau, bon, jeune …', 'Een kleine groep korte, veelgebruikte bijvoeglijke naamwoorden staat <b>vóór</b> het woord: <i>un <b>petit</b> café, une <b>belle</b> ville, un <b>bon</b> restaurant</i>. <b>Waarom?</b> Het zijn oude, heel frequente woorden die een vaste eenheid met het zelfstandig naamwoord vormen; ezelsbrug <b>BAGS</b>: Beauty, Age, Goodness, Size.'],
        ['beau → bel, nouveau → nouvel, vieux → vieil', 'Vóór een mannelijk woord met een klinker zeg je <i>un <b>bel</b> appartement, un <b>nouvel</b> ami, un <b>vieil</b> homme</i>. <b>Waarom?</b> Twee klinkers na elkaar botsen (<i>beau appartement</i>); met de extra l loopt de zin vloeiend door.']] },
    ww: { n: 'le verbe',
      html: 'Franse werkwoorden vallen in drie groepen: op <b>-er</b> (<i>parler</i>, veruit de grootste groep), op <b>-ir</b> (<i>finir</i>) en de rest: <b>-re, -oir</b> en onregelmatige (<i>prendre, pouvoir</i>). Het onderwerp mag je <b>nooit weglaten</b>, want veel vormen klinken hetzelfde: <i>je parle, tu parles, il parle</i>.',
      ex: [['parler, finir, prendre', 'praten, eindigen, nemen'], ['Je parle français.', 'Ik spreek Frans.'], ['Où est-ce que tu habites ?', 'Waar woon je?']] },
    bw: { n: 'l’adverbe',
      html: 'Veel Franse bijwoorden maak je met <b>-ment</b> achter de vrouwelijke vorm van het bijvoeglijk naamwoord: <i>lente → lentement, heureuse → heureusement</i>. Een kort bijwoord staat <b>direct achter</b> de persoonsvorm: <i>Je mange <b>souvent</b> ici</i>, en in de passé composé tussen hulpwerkwoord en deelwoord: <i>J’ai <b>bien</b> dormi</i>.',
      ex: [['Elle parle lentement.', 'Ze praat langzaam.'], ['J’ai bien dormi.', 'Ik heb goed geslapen.'], ['Il vient souvent ici.', 'Hij komt hier vaak.']],
      uz: [['bien, mal, vite', 'Bij <i>bon</i> hoort het bijwoord <b>bien</b>, bij <i>mauvais</i> hoort <b>mal</b>, en "snel" is <b>vite</b> (niet <i>rapide</i>): <i>Tu chantes bien</i>. <b>Waarom?</b> Het zijn oude Latijnse bijwoorden (<i>bene, male</i>) die al bestonden voordat -ment de gewone manier werd.'],
        ['vraiment, évidemment', '<i>vrai → vraiment</i> (zonder e) en <i>évident → évidemment</i>, <i>constant → constamment</i>. <b>Waarom?</b> Eindigt de mannelijke vorm al op een klinker, dan is de extra -e niet nodig; en bij -ent/-ant versmolt de uitgang met -ment tot -emment/-amment (allebei uitgesproken als "amã").']] },
    vnw: { n: 'le pronom',
      html: 'Het Frans heeft al deze soorten, plus twee kleine woordjes die het Nederlands niet zo kent: <b>y</b> (daar, eraan) en <b>en</b> (ervan, er … van). Voornaamwoorden voor het voorwerp staan <b>vóór</b> het werkwoord: <i>Je <b>le</b> vois</i>.',
      ex: [['Léa est fatiguée. Elle va dormir.', 'Léa is moe. Ze gaat slapen.'], ['Le livre ? Je l’ai acheté hier.', 'Het boek? Ik heb het gisteren gekocht.'], ['J’y vais.', 'Ik ga erheen.'], ['J’en veux deux.', 'Ik wil er twee (van).']] },
    pers: { n: 'les pronoms personnels sujets',
      html: 'Het onderwerp moet er altijd bij staan. <b>Je</b> wordt <b>j’</b> vóór een klinker: <i>j’habite</i>. In spreektaal is <b>on</b> het gewone woord voor "wij": <i>On va au cinéma ?</i> Het werkwoord staat dan in de 3e persoon enkelvoud.',
      table: [['', 'enkelvoud', 'meervoud'], ['1e persoon', 'je (ik)', 'nous (wij) · on (we, spreektaal)'], ['2e persoon', 'tu (jij)', 'vous (jullie, u)'], ['3e persoon', 'il (hij) · elle (zij) · on (men)', 'ils · elles (zij)']],
      ex: [['J’habite à Lyon.', 'Ik woon in Lyon.'], ['On mange ?', 'Zullen we eten?'], ['Vous êtes de Bruxelles ?', 'Komt u / komen jullie uit Brussel?']],
      uz: [['moi, toi, lui, eux', 'Los, na een voorzetsel of voor nadruk gebruik je een andere vorm: <i><b>Moi</b>, je reste</i>, <i>avec <b>toi</b></i>, <i>chez <b>eux</b></i>. Niet <i>avec je</i>. <b>Waarom?</b> <i>je, tu, il</i> zijn zwakke vormen die aan een werkwoord vast moeten zitten; staat er geen werkwoord direct achter, dan heb je de sterke (beklemtoonde) vorm nodig.'],
        ['ils voor een gemengde groep', 'Eén man in een groep vrouwen en je zegt <i>ils</i>. <b>Waarom?</b> In de Franse grammatica is mannelijk de neutrale vorm voor gemengde groepen; <i>elles</i> is alleen voor uitsluitend vrouwelijke groepen.']] },
    bez: { n: 'les possessifs',
      html: 'Het bezittelijk voornaamwoord past zich aan bij <b>het bezit</b>, niet bij de bezitter: <i><b>sa</b> mère</i> is "zijn moeder" én "haar moeder", want <i>mère</i> is vrouwelijk.',
      table: [['', 'mannelijk', 'vrouwelijk', 'meervoud'], ['mijn', 'mon', 'ma', 'mes'], ['jouw', 'ton', 'ta', 'tes'], ['zijn / haar', 'son', 'sa', 'ses'], ['ons', 'notre', 'notre', 'nos'], ['jullie / uw', 'votre', 'votre', 'vos'], ['hun', 'leur', 'leur', 'leurs']],
      ex: [['mon frère et ma sœur', 'mijn broer en mijn zus'], ['ses enfants', 'zijn / haar kinderen'], ['Ce livre est à moi.', 'Dit boek is van mij.']],
      uz: [['mon amie, ton école', 'Vóór een vrouwelijk woord dat met een klinker begint zeg je <b>mon, ton, son</b>: <i>mon amie, son idée</i>, niet <i>ma amie</i>. <b>Waarom?</b> Twee klinkers na elkaar botsen; met <i>mon</i> hoor je een n als overgang.']] },
    aanw: { n: 'les démonstratifs',
      html: 'Het Frans maakt geen verschil tussen "deze" en "die": <b>ce, cette, ces</b> betekenen allebei. Wil je het verschil wel maken, dan plak je <b>-ci</b> (hier) of <b>-là</b> (daar) achter het woord: <i>ce livre-ci, ce livre-là</i>.',
      table: [['', 'enkelvoud', 'meervoud'], ['mannelijk', 'ce (cet)', 'ces'], ['vrouwelijk', 'cette', 'ces']],
      ex: [['ce pull, cette veste, ces chaussures', 'deze/die trui, jas, schoenen'], ['Je préfère celui-là.', 'Ik heb liever die daar.'], ['C’est quoi, ça ?', 'Wat is dat?']],
      uz: [['cet homme, cet été', 'Vóór een mannelijk woord met een klinker of stomme h wordt <i>ce</i> → <b>cet</b>. <b>Waarom?</b> <i>ce été</i> geeft twee botsende klinkers; de t maakt de overgang (je hoort "sè-té-té").']] },
    obj: { n: 'les pronoms compléments',
      html: 'Voor het <b>lijdend voorwerp</b>: <i>me, te, le/la, nous, vous, les</i>. Voor het <b>meewerkend voorwerp</b> (aan wie): <i>me, te, lui, nous, vous, leur</i>. Ze staan <b>vóór</b> het werkwoord waar ze bij horen: <i>Je <b>le</b> vois</i>, <i>Je vais <b>lui</b> téléphoner</i>. Twee tegelijk? Dan is de volgorde: <i>me/te/nous/vous → le/la/les → lui/leur → y → en</i>.',
      table: [['', 'lijdend voorwerp', 'meewerkend voorwerp'], ['mij', 'me (m’)', 'me (m’)'], ['jou', 'te (t’)', 'te (t’)'], ['hem / haar / het', 'le, la (l’)', 'lui'], ['ons', 'nous', 'nous'], ['jullie / u', 'vous', 'vous'], ['hen / ze', 'les', 'leur']],
      ex: [['Le café ? Je le prends sans sucre.', 'De koffie? Ik neem hem zonder suiker.'], ['Je t’appelle demain.', 'Ik bel je morgen.'], ['Je lui donne un cadeau.', 'Ik geef hem / haar een cadeau.'], ['Je te le prête.', 'Ik leen het je.']],
      uz: [['Donne-le-moi !', 'In de bevestigende gebiedende wijs staan de voornaamwoorden <b>achter</b> het werkwoord, met streepjes, en <i>me/te</i> worden <i>moi/toi</i>: <i>Donne-le-moi</i>. <b>Waarom?</b> Een bevel begint met het werkwoord; de zwakke vormen <i>me/te</i> kunnen niet aan het eind met klemtoon staan, dus komt de sterke vorm.']] },
    wederk: { n: 'les verbes pronominaux', k: 'Iets wat je bij jezelf doet: zich wassen, zich vervelen. Me, te, se …',
      html: 'Je herkent ze aan <b>se</b> vóór de infinitief: <i>se lever</i> (opstaan), <i>s’appeler</i> (heten), <i>se doucher</i> (douchen). Het voornaamwoord verandert mee: <i>je <b>me</b> lève, tu <b>te</b> lèves, il <b>se</b> lève, nous <b>nous</b> levons</i>. In de passé composé altijd met <b>être</b>: <i>je me suis levé(e)</i>.',
      ex: [['Je m’appelle Mark.', 'Ik heet Mark.'], ['Je me lève à sept heures.', 'Ik sta om zeven uur op.'], ['Elle s’est couchée tard.', 'Ze is laat naar bed gegaan.']],
      uz: [['Elle s’est lavé les mains.', 'Normaal past het deelwoord zich aan (<i>elle s’est lavé<b>e</b></i>), maar niet als er nog een lijdend voorwerp achter komt: <i>elle s’est lavé les mains</i>. <b>Waarom?</b> Dan is <i>les mains</i> het lijdend voorwerp en <i>se</i> alleen "bij zichzelf"; het deelwoord richt zich alleen naar een lijdend voorwerp dat ervóór staat.']] },
    betr: { n: 'les pronoms relatifs',
      html: '<b>Qui</b> is het onderwerp van de bijzin, <b>que</b> het lijdend voorwerp: <i>l’homme <b>qui</b> parle</i>, <i>le film <b>que</b> j’ai vu</i>. Het gaat dus niet om persoon of ding. <b>Où</b> is voor plaats en tijd, <b>dont</b> vervangt iets met <i>de</i>: <i>le livre <b>dont</b> je parle</i> (parler <i>de</i>). Na andere voorzetsels: <b>lequel, laquelle</b>.',
      ex: [['La fille qui chante est ma sœur.', 'Het meisje dat zingt is mijn zus.'], ['Le film que j’ai vu était super.', 'De film die ik zag was super.'], ['La ville où j’habite est calme.', 'De stad waar ik woon is rustig.'], ['C’est le livre dont j’ai besoin.', 'Dat is het boek dat ik nodig heb.']],
      uz: [['ce qui, ce que, ce dont', 'Is er geen woord om naar te verwijzen ("wat"), dan zet je <b>ce</b> ervoor: <i>Je ne comprends pas <b>ce que</b> tu dis</i>. <b>Waarom?</b> Een Frans betrekkelijk voornaamwoord heeft altijd iets nodig om op terug te slaan; <i>ce</i> (dat) vult die lege plek.']] },
    vraag: { n: 'les mots interrogatifs',
      html: 'De belangrijkste: <i>qui</i> (wie), <i>que / quoi</i> (wat), <i>où</i> (waar), <i>quand</i> (wanneer), <i>comment</i> (hoe), <i>pourquoi</i> (waarom), <i>combien</i> (hoeveel), <i>quel / quelle</i> (welk).',
      ex: [['Où est-ce que tu habites ?', 'Waar woon je?'], ['Tu fais quoi ?', 'Wat doe je? (spreektaal)'], ['Quelle heure est-il ?', 'Hoe laat is het?']],
      uz: [['que wordt quoi', 'Aan het begin zeg je <i><b>Que</b> fais-tu ?</i> of <i><b>Qu’est-ce que</b> tu fais ?</i>, maar achteraan en na een voorzetsel wordt het <b>quoi</b>: <i>Tu fais <b>quoi</b> ?</i>, <i>De <b>quoi</b> tu parles ?</i> <b>Waarom?</b> <i>que</i> is een zwakke vorm die vóór een werkwoord moet staan; met klemtoon (aan het eind, na een voorzetsel) heb je de sterke vorm nodig, net als <i>me → moi</i>.']] },
    vz: { n: 'la préposition',
      html: 'De twee belangrijkste zijn <b>à</b> (naar, in, om, aan) en <b>de</b> (van, uit). Ze versmelten met <i>le</i> en <i>les</i>: <i>au, aux, du, des</i>. Bij landen: <b>en</b> voor vrouwelijke landen (<i>en France</i>), <b>au</b> voor mannelijke (<i>au Canada</i>), <b>aux</b> voor meervoud (<i>aux Pays-Bas</i>), en <b>à</b> voor steden (<i>à Paris</i>).',
      ex: [['Je vais à Paris, en France.', 'Ik ga naar Parijs, in Frankrijk.'], ['Je viens des Pays-Bas.', 'Ik kom uit Nederland.'], ['chez le médecin', 'bij de dokter'], ['depuis deux ans', 'sinds twee jaar / al twee jaar']],
      uz: [['au Mexique, au Cambodge', 'Landen op <b>-e</b> zijn vrouwelijk (<i>en Belgique</i>), maar <i>le Mexique, le Cambodge, le Mozambique, le Zimbabwe</i> zijn mannelijk: <i>au Mexique</i>. <b>Waarom?</b> Deze namen komen niet uit het Latijn op -a, zoals de vrouwelijke landen (<i>Francia, Belgica</i>), maar uit andere talen; ze kregen het standaardgeslacht mannelijk.']] },
    vw: { n: 'la conjonction',
      html: 'De gewone: <i>et</i> (en), <i>ou</i> (of), <i>mais</i> (maar), <i>donc</i> (dus), <i>parce que</i> (omdat), <i>quand</i> (als, wanneer), <i>si</i> (als, indien), <i>que</i> (dat). Let op: sommige voegwoorden vragen de <b>subjonctif</b>: <i>bien que, pour que, avant que, à condition que</i>.',
      ex: [['Je reste parce qu’il pleut.', 'Ik blijf omdat het regent.'], ['Bien qu’il soit tard, je travaille.', 'Hoewel het laat is, werk ik.'], ['Si tu veux, on y va.', 'Als je wilt, gaan we.']],
      uz: [['si + il = s’il', '<i>si</i> wordt alleen vóór <i>il</i> en <i>ils</i> <b>s’</b>: <i>s’il vous plaît</i>, maar <i>si elle veut</i>. <b>Waarom?</b> Twee i-klanken achter elkaar smolten samen; bij <i>elle</i> is er geen dubbele i, dus blijft <i>si</i> heel.']] },
    telw: { n: 'les nombres',
      html: 'Tot 69 gaat het tellen zoals je verwacht. Daarna rekent het Frans van Frankrijk: <b>soixante-dix</b> (60+10 = 70), <b>quatre-vingts</b> (4×20 = 80), <b>quatre-vingt-dix</b> (4×20+10 = 90).',
      ex: [['vingt et un', 'eenentwintig'], ['soixante-quinze', 'vijfenzeventig'], ['quatre-vingt-dix-neuf', 'negenennegentig'], ['le premier, la première', 'de eerste']],
      uz: [['septante, nonante 🇧🇪 🇨🇭', 'In België en Zwitserland zeg je <b>septante</b> (70) en <b>nonante</b> (90), in delen van Zwitserland ook <b>huitante</b> (80). <b>Waarom?</b> Dat zijn de oude, regelmatige Latijnse vormen; in Frankrijk won het tellen in twintigtallen (een Keltisch en Normandisch gebruik), in België en Zwitserland niet.'],
        ['quatre-vingts, maar quatre-vingt-un', '<i>quatre-vingts</i> en <i>deux cents</i> krijgen een <b>-s</b>, maar die valt weg zodra er nog een getal volgt: <i>quatre-vingt-trois, deux cent dix</i>. <b>Waarom?</b> De -s is een meervoud (vier twintigen); volgt er nog een getal, dan is het geen rond veelvoud meer en vervalt het meervoud.']] },
    tussenw: { n: 'l’interjection',
      html: 'Veelgehoord in gesproken Frans: <i>Oh là là !</i> (verbazing, schrik: niet per se positief), <i>Bof.</i> (mwah), <i>Aïe !</i> (au), <i>Zut !</i> (verdorie), <i>Hein ?</i> (hè?), <i>Bah oui.</i> (ja, natuurlijk), <i>Tiens !</i> (hé, kijk).',
      ex: [['Oh là là, quel monde !', 'Jeetje, wat een drukte!'], ['Bof, pas terrible.', 'Mwah, niet geweldig.'], ['Aïe, ça fait mal !', 'Au, dat doet pijn!']] },
    onderwerp: { n: 'le sujet',
      html: 'Het onderwerp staat vóór het werkwoord en mag <b>nooit ontbreken</b>. Ook waar het Nederlands "het" of "er" zegt, staat een onderwerp: <i><b>Il</b> pleut</i>, <i><b>Il</b> y a un problème</i>, <i><b>C’</b>est facile</i>.',
      ex: [['Ma sœur habite à Lille.', 'Mijn zus woont in Lille.'], ['Il pleut.', 'Het regent.'], ['Il y a un problème.', 'Er is een probleem.']] },
    pv: { n: 'le verbe conjugué',
      html: 'De persoonsvorm past zich aan het onderwerp aan. Veel uitgangen <b>hoor je niet</b>: <i>parle, parles, parle, parlent</i> klinken precies hetzelfde. Daarom is het onderwerp verplicht. In het Frans blijft de volgorde <b>onderwerp, persoonsvorm</b>, ook na een tijdsbepaling: <i>Demain <b>je vais</b> à Paris</i> (niet zoals in het Nederlands "morgen ga ik").',
      ex: [['Ils parlent français.', 'Ze spreken Frans.'], ['Demain je vais à Paris.', 'Morgen ga ik naar Parijs.']] },
    lv: { n: 'le complément d’objet direct (COD)',
      html: 'Het lijdend voorwerp volgt <b>zonder voorzetsel</b> op het werkwoord: <i>Je regarde <b>la télé</b></i>. Als voornaamwoord: <i>le, la, les</i>. Belangrijk voor de spelling: staat het lijdend voorwerp <b>vóór</b> een deelwoord met <i>avoir</i>, dan past het deelwoord zich aan: <i>la lettre que j’ai écrit<b>e</b></i>.',
      ex: [['Je regarde la télé.', 'Ik kijk tv.'], ['Je la regarde.', 'Ik kijk ernaar.'], ['Les photos ? Je les ai prises hier.', 'De foto’s? Ik heb ze gisteren gemaakt.']],
      uz: [['attendre, écouter, regarder, chercher', 'In het Nederlands zeg je wachten <i>op</i>, luisteren <i>naar</i>, kijken <i>naar</i>, zoeken <i>naar</i>; in het Frans <b>zonder</b> voorzetsel: <i>J’attends le bus</i>, <i>J’écoute la radio</i>. <b>Waarom?</b> In deze Franse werkwoorden zit het "op/naar" al in de betekenis; een extra voorzetsel zou dubbelop zijn.']] },
    mv: { n: 'le complément d’objet indirect (COI)',
      html: 'Het meewerkend voorwerp krijgt <b>à</b>: <i>Je donne le livre <b>à Paul</b></i>. Als voornaamwoord: <b>lui</b> (aan hem én aan haar) en <b>leur</b> (aan hen).',
      ex: [['Je téléphone à ma mère.', 'Ik bel mijn moeder.'], ['Je lui téléphone.', 'Ik bel haar / hem.'], ['Je leur ai dit la vérité.', 'Ik heb hun de waarheid verteld.']],
      uz: [['téléphoner à, demander à, répondre à', 'In het Nederlands bel je <i>iemand</i>, in het Frans bel je <b>aan</b> iemand: <i>Je téléphone <b>à</b> Léa → Je <b>lui</b> téléphone</i> (niet <i>je la téléphone</i>). <b>Waarom?</b> Het Frans ziet bellen, vragen en antwoorden als iets wat je <i>aan</i> iemand richt, zoals geven; daarom een meewerkend voorwerp.']] },
    bijzin: { n: 'la proposition subordonnée',
      html: 'Goed nieuws: in een Franse bijzin blijft de woordvolgorde <b>gewoon</b>: onderwerp, werkwoord, rest. Het werkwoord gaat niet naar het eind zoals in het Nederlands. <i>Je sais <b>que tu as raison</b></i> (letterlijk: dat jij hebt gelijk). Na sommige hoofdzinnen (wens, gevoel, noodzaak) staat het werkwoord in de bijzin in de subjonctif.',
      ex: [['Je pense qu’il vient demain.', 'Ik denk dat hij morgen komt.'], ['Quand j’ai le temps, je lis.', 'Als ik tijd heb, lees ik.'], ['Je veux que tu viennes.', 'Ik wil dat je komt.']] },
    ontkenning: { n: 'la négation',
      html: 'De Franse ontkenning heeft <b>twee delen</b> rond de persoonsvorm: <b>ne … pas</b>. <i>Je <b>ne</b> sais <b>pas</b></i>. Andere paren: <i>ne … plus</i> (niet meer), <i>ne … jamais</i> (nooit), <i>ne … rien</i> (niets), <i>ne … personne</i> (niemand), <i>ne … que</i> (alleen maar). In spreektaal valt <i>ne</i> meestal weg: <i>Je sais pas</i>.',
      ex: [['Je ne parle pas espagnol.', 'Ik spreek geen Spaans.'], ['Il ne fume plus.', 'Hij rookt niet meer.'], ['Je n’ai rien vu.', 'Ik heb niets gezien.'], ['J’sais pas.', 'Weet ik niet. (spreektaal)']],
      uz: [['Je n’ai vu personne.', 'In de passé composé staat <i>pas, plus, jamais, rien</i> tussen hulpwerkwoord en deelwoord, maar <b>personne</b> komt erachter: <i>Je n’ai vu personne</i>. <b>Waarom?</b> <i>personne</i> is van oorsprong een zelfstandig naamwoord (een persoon) en staat dus op de plek van het lijdend voorwerp, na het deelwoord.']] },
    vraagzin: { n: 'la phrase interrogative',
      html: 'Drie manieren, van informeel naar formeel: (1) alleen <b>toon omhoog</b>: <i>Tu viens ?</i> (2) met <b>est-ce que</b>: <i>Est-ce que tu viens ?</i> (3) <b>inversie</b>: <i>Viens-tu ?</i> In het Frans staat vóór het vraagteken een spatie.',
      ex: [['Tu viens ce soir ?', 'Kom je vanavond?'], ['Est-ce que vous parlez anglais ?', 'Spreekt u Engels?'], ['Où allez-vous ?', 'Waar gaat u heen?']],
      uz: [['A-t-il … ? Parle-t-elle … ?', 'Bij inversie komt er een <b>-t-</b> tussen als het werkwoord op een klinker eindigt en <i>il, elle</i> of <i>on</i> volgt: <i>A-<b>t</b>-il faim ?</i> <b>Waarom?</b> <i>a-il</i> geeft twee botsende klinkers; de t (die bij andere werkwoorden al klinkt: <i>est-il, fait-il</i>) maakt de overgang.']] },
    infinitief: { n: 'l’infinitif',
      html: 'De infinitief eindigt op <b>-er, -ir, -re</b> of <b>-oir</b>. Na een vervoegd werkwoord volgt hij direct (<i>Je veux <b>partir</b></i>), of met <b>à</b> of <b>de</b>, afhankelijk van het eerste werkwoord: <i>commencer <b>à</b> lire</i>, <i>essayer <b>de</b> dormir</i>. Dat voorzetsel leer je bij het werkwoord. De ontkenning staat er in zijn geheel vóór: <i><b>ne pas</b> fumer</i>.',
      ex: [['Je veux partir.', 'Ik wil weggaan.'], ['Il commence à pleuvoir.', 'Het begint te regenen.'], ['J’ai oublié de fermer la porte.', 'Ik ben vergeten de deur dicht te doen.'], ['Ne pas toucher.', 'Niet aanraken.']] },
    vervoegen: { n: 'la conjugaison',
      html: 'Regelmatige werkwoorden op <b>-er</b> krijgen in de tegenwoordige tijd: <i>-e, -es, -e, -ons, -ez, -ent</i>. Daarvan <b>hoor</b> je alleen <i>-ons</i> en <i>-ez</i>; de rest is stom.',
      table: [['', 'parler', 'finir', 'vendre'], ['je', 'parle', 'finis', 'vends'], ['tu', 'parles', 'finis', 'vends'], ['il / elle / on', 'parle', 'finit', 'vend'], ['nous', 'parlons', 'finissons', 'vendons'], ['vous', 'parlez', 'finissez', 'vendez'], ['ils / elles', 'parlent', 'finissent', 'vendent']],
      ex: [['Nous parlons français.', 'Wij spreken Frans.'], ['Ils finissent à six heures.', 'Ze zijn om zes uur klaar.']],
      uz: [['nous mangeons, nous commençons', 'Bij werkwoorden op <b>-ger</b> en <b>-cer</b> schrijf je in de nous-vorm <i>mang<b>e</b>ons</i> en <i>commen<b>ç</b>ons</i>. <b>Waarom?</b> Vóór een o klinkt g als in "goal" en c als k; de extra e en de cedille houden de zachte klank van de infinitief vast.']] },
    stam: { n: 'le radical et la terminaison',
      html: 'Haal de uitgang <i>-er, -ir, -re</i> van de infinitief af en je hebt de stam: <i>parl-er → parl-</i>. Daar komen de uitgangen achter. Voor de <b>futur</b> en <b>conditionnel</b> is de hele infinitief de stam: <i>parler-ai, parler-ais</i>.',
      ex: [['parl-er → je parl-e', 'praten → ik praat'], ['fin-ir → nous fin-issons', 'eindigen → wij eindigen'], ['parler → je parler-ai', 'praten → ik zal praten']] },
    stamwissel: { n: 'les verbes à deux radicaux', t: 'Stamwisseling', k: 'De stam verandert in sommige personen: j’achète, nous achetons.',
      gen: 'Bij een aantal werkwoorden verandert de <b>stam</b> in een deel van de vormen. In het Nederlands ken je dat van <i>ik loop, wij lopen</i> (alleen in spelling) of <i>ik kan, wij kunnen</i>.',
      html: 'In het Frans heeft de stam vaak een andere vorm in de vier vormen waar de uitgang <b>stom</b> is (je, tu, il, ils) dan bij <i>nous</i> en <i>vous</i>: het zogenoemde <b>laarsje</b>. <i>J’ach<b>è</b>te, nous achetons</i>; <i>j’appe<b>ll</b>e, nous appelons</i>; <i>je pr<b>é</b>f<b>è</b>re, nous préférons</i>; <i>j’envo<b>i</b>e, nous envoyons</i>.',
      ex: [['J’achète du pain.', 'Ik koop brood.'], ['Nous achetons du pain.', 'Wij kopen brood.'], ['Je m’appelle Zoé.', 'Ik heet Zoé.'], ['Ils préfèrent le thé.', 'Ze drinken liever thee.']],
      uz: [['Waarom j’achète met è?', 'De regel lijkt een uitzondering, maar heeft een <b>reden</b>: als de uitgang stom is, valt de klemtoon op de stam, en een beklemtoonde e moet open klinken (è). Bij <i>nous achetons</i> ligt de klemtoon op -ons en blijft de e zwak.']] },
    persoon: { n: 'la personne et le nombre',
      html: 'Zes personen, maar let op twee dingen: <b>vous</b> is zowel "jullie" als beleefd "u" (ook tegen één persoon), en <b>on</b> betekent in spreektaal "wij" maar krijgt de vorm van <i>il/elle</i>.',
      ex: [['Vous avez raison, madame.', 'U hebt gelijk, mevrouw.'], ['On est prêts.', 'We zijn klaar.']] },
    onregelmatig: { n: 'les verbes réguliers et irréguliers',
      html: 'Ongeveer 90% van de Franse werkwoorden eindigt op <b>-er</b> en is regelmatig. Maar juist de meest gebruikte zijn onregelmatig: <i>être, avoir, aller, faire, pouvoir, vouloir, devoir, savoir, venir, prendre, dire, voir</i>. Die leer je het best uit je hoofd, in zinnen.',
      table: [['', 'être', 'avoir', 'aller', 'faire'], ['je', 'suis', 'ai', 'vais', 'fais'], ['tu', 'es', 'as', 'vas', 'fais'], ['il / elle / on', 'est', 'a', 'va', 'fait'], ['nous', 'sommes', 'avons', 'allons', 'faisons'], ['vous', 'êtes', 'avez', 'allez', 'faites'], ['ils / elles', 'sont', 'ont', 'vont', 'font']],
      ex: [['Je suis néerlandais.', 'Ik ben Nederlander.'], ['Vous faites quoi ?', 'Wat doen jullie?']],
      uz: [['aller: het enige onregelmatige -er-werkwoord', '<i>aller</i> eindigt op -er maar gaat <i>je vais, tu vas, il va</i>. <b>Waarom?</b> Het is uit drie Latijnse werkwoorden samengegroeid (<i>ambulare, vadere, ire</i>): <i>all-</i>, <i>va-</i> en in de toekomende tijd <i>ir-</i> (<i>j’irai</i>).'],
        ['vous êtes, vous faites, vous dites', 'Alleen deze drie hebben bij <i>vous</i> geen <i>-ez</i>. <b>Waarom?</b> Het zijn zulke oude en veelgebruikte vormen dat ze de Latijnse uitgang <i>-tis</i> (<i>estis, facitis, dicitis</i>) hebben bewaard in plaats van zich aan te passen.']] },
    hulpww: { n: 'l’auxiliaire',
      html: 'Voor de voltooide tijden gebruikt het Frans <b>avoir</b> (meestal) of <b>être</b>. Met <i>être</i> gaan alle wederkerende werkwoorden en een vaste groep werkwoorden van beweging of verandering: <i>aller, venir, arriver, partir, entrer, sortir, monter, descendre, naître, mourir, rester, tomber, retourner, devenir</i>. Met <i>être</i> past het deelwoord zich aan het onderwerp aan: <i>elle est partie</i>.',
      ex: [['J’ai mangé.', 'Ik heb gegeten.'], ['Elle est arrivée hier.', 'Ze is gisteren aangekomen.'], ['Nous nous sommes levés tôt.', 'We zijn vroeg opgestaan.']],
      uz: [['J’ai été, j’ai couru, j’ai marché', 'Niet alles wat in het Nederlands "zijn" krijgt, krijgt <i>être</i>: <i>ik ben geweest</i> = <i>j’<b>ai</b> été</i>, <i>ik ben gerend</i> = <i>j’<b>ai</b> couru</i>, <i>ik ben begonnen</i> = <i>j’<b>ai</b> commencé</i>. <b>Waarom?</b> De Franse être-groep is een korte, gesloten lijst van werkwoorden die een verplaatsing naar een eindpunt of een verandering van toestand uitdrukken; alles daarbuiten krijgt <i>avoir</i>.'],
        ['J’ai sorti la poubelle.', '<i>sortir, monter, descendre, passer, rentrer</i> krijgen <b>avoir</b> zodra er een lijdend voorwerp bij staat: <i>Je <b>suis</b> sorti</i> (ik ben uitgegaan), maar <i>J’<b>ai</b> sorti la poubelle</i> (ik heb de vuilnisbak buitengezet). <b>Waarom?</b> Met een lijdend voorwerp is het geen beweging van jezelf meer, maar een handeling met iets anders; daar hoort <i>avoir</i> bij.']] },
    deelwoord: { n: 'le participe passé',
      html: 'Regelmatig: <b>-er → -é</b> (<i>parlé</i>), <b>-ir → -i</b> (<i>fini</i>), <b>-re → -u</b> (<i>vendu</i>). Veel gebruikte zijn onregelmatig: <i>été, eu, fait, pris, dit, vu, pu, voulu, dû, mis, écrit, ouvert, né, mort</i>. Met <i>être</i> past het deelwoord zich aan het onderwerp aan (<i>elles sont parti<b>es</b></i>).',
      ex: [['J’ai fini mon travail.', 'Ik heb mijn werk af.'], ['Elle a pris le train.', 'Ze heeft de trein genomen.'], ['Ils sont venus hier.', 'Ze zijn gisteren gekomen.']],
      uz: [['la lettre que j’ai écrite', 'Met <i>avoir</i> blijft het deelwoord normaal onveranderd, maar staat het <b>lijdend voorwerp ervóór</b>, dan past het zich aan: <i>J’ai écrit la lettre</i>, maar <i>la lettre que j’ai écrit<b>e</b></i>, <i>je les ai vu<b>s</b></i>. <b>Waarom?</b> Toen de regel in de 16e eeuw werd vastgelegd, was het idee: wie schrijft, weet bij het deelwoord alleen het geslacht van wat al genoemd is. Meestal hoor je het verschil niet; wel bij <i>prise, faite, écrite, mise</i>.']] },
    gerundio: { n: 'le gérondif', t: 'Gérondif', k: 'En + -ant: iets doen terwijl of doordat je iets anders doet: en mangeant.', a: ['gérondif', 'participe présent'],
      gen: 'Het Nederlands heeft een <b>onvoltooid deelwoord</b> op -end: <i>lopend, zingend</i>. Je gebruikt het om te zeggen dat twee dingen tegelijk gebeuren: <i><b>zingend</b> liep hij naar huis</i>.',
      html: 'De <b>gérondif</b> is <b>en + stam van de nous-vorm + -ant</b>: <i>nous parlons → en parlant</i>. Je zegt ermee dat iets <b>tegelijk</b> gebeurt (terwijl) of <b>hoe</b> iets lukt (door te): <i>J’apprends le français <b>en écoutant</b> des podcasts</i>. Het onderwerp van beide handelingen is hetzelfde. Voor "aan het … zijn" gebruikt het Frans iets anders: <b>être en train de</b> + infinitief.',
      ex: [['Il travaille en écoutant de la musique.', 'Hij werkt terwijl hij naar muziek luistert.'], ['On apprend en faisant des erreurs.', 'Je leert door fouten te maken.'], ['Je suis en train de manger.', 'Ik ben aan het eten.']],
      uz: [['étant, ayant, sachant', 'Drie werkwoorden maken de vorm niet van de nous-vorm: <i>être → <b>étant</b></i>, <i>avoir → <b>ayant</b></i>, <i>savoir → <b>sachant</b></i>. <b>Waarom?</b> Ze gebruiken dezelfde oude stam als hun subjonctif (<i>ayons, sachons</i>), niet die van de gewone tegenwoordige tijd.']] },
    passief: { n: 'la voix passive',
      html: 'Het passief is <b>être + voltooid deelwoord</b>, en het deelwoord past zich aan: <i>La lettre <b>est écrite</b> par Paul</i>. De dader krijgt <b>par</b>. Het Frans vermijdt het passief vaak en zegt liever <b>on</b>: <i>On parle français ici</i> (hier wordt Frans gesproken), of gebruikt een wederkerende vorm: <i>Ça se dit</i> (dat wordt gezegd).',
      ex: [['Le musée a été construit en 1900.', 'Het museum is in 1900 gebouwd.'], ['On m’a volé mon vélo.', 'Mijn fiets is gestolen.'], ['Ça ne se fait pas.', 'Dat doe je niet. / Dat hoort niet.']],
      uz: [['On m’a donné un livre.', '"Mij werd een boek gegeven" kan in het Frans niet met <i>je</i> als onderwerp: niet <i>J’ai été donné un livre</i>, maar <i><b>On</b> m’a donné un livre</i>. <b>Waarom?</b> Alleen een lijdend voorwerp kan in het Frans onderwerp van een passieve zin worden; <i>me</i> is hier meewerkend voorwerp.']] },
    tijdwijs: { n: 'le temps et le mode',
      html: 'Het Frans heeft vier wijzen die je echt nodig hebt: <b>indicatif</b> (feiten), <b>subjonctif</b> (wens, gevoel, twijfel, noodzaak), <b>conditionnel</b> (zou) en <b>impératif</b> (bevel). In gesproken Frans kom je ver met vijf tijden: présent, passé composé, imparfait, futur proche en futur simple. De <b>passé simple</b> kom je alleen in boeken tegen.',
      ex: [['Il vient.', 'Hij komt. (feit)'], ['Je veux qu’il vienne.', 'Ik wil dat hij komt. (wens)'], ['Il viendrait.', 'Hij zou komen.'], ['Viens !', 'Kom!']] },
    presente: { n: 'le présent', k: 'Wat nu gebeurt, wat je gewoonlijk doet: ik werk, ik woon in Lyon.', gen: 'De <b>tegenwoordige tijd</b> gebruik je voor wat nu gebeurt, wat altijd zo is of wat je gewoonlijk doet: <i>ik werk</i>, <i>ik woon in Lyon</i>, <i>ik drink elke ochtend koffie</i>.',
      html: 'Het Frans heeft één tegenwoordige tijd voor "ik eet" én "ik ben aan het eten": <i>Je mange</i>. Wil je benadrukken dat het nu bezig is: <i>Je suis <b>en train de</b> manger</i>. Met <b>depuis</b> gebruik je ook de présent voor iets dat al een tijd duurt: <i>J’habite ici <b>depuis</b> trois ans</i>.',
      ex: [['Je travaille à Rotterdam.', 'Ik werk in Rotterdam.'], ['Qu’est-ce que tu fais ?', 'Wat ben je aan het doen?'], ['J’apprends le français depuis un an.', 'Ik leer al een jaar Frans.']] },
    indefinido: { n: 'le passé composé', t: 'Passé composé', k: 'De verleden tijd voor afgeronde gebeurtenissen: hier, j’ai mangé une crêpe.', a: ['passé composé', 'passé simple'],
      gen: 'Dit is een <b>verleden tijd</b> voor een afgeronde gebeurtenis op een bepaald moment: <i>gisteren <b>at</b> ik een crêpe</i>, <i>in 2019 <b>reisde</b> ik naar Marseille</i>. Het verhaal gaat ermee vooruit: eerst dit, toen dat.',
      html: 'In gesproken Frans vertel je afgeronde gebeurtenissen met de <b>passé composé</b>: <b>avoir</b> of <b>être</b> in de tegenwoordige tijd + voltooid deelwoord. Hij dekt zowel het Nederlandse "ik at" als "ik heb gegeten": <i>Hier, j’<b>ai mangé</b> une crêpe</i>. De <b>passé simple</b> (<i>il mangea</i>) betekent hetzelfde, maar staat alleen in boeken en sprookjes.',
      table: [['', 'parler (avoir)', 'aller (être)'], ['je / j’', 'ai parlé', 'suis allé(e)'], ['tu', 'as parlé', 'es allé(e)'], ['il / elle', 'a parlé', 'est allé / allée'], ['nous', 'avons parlé', 'sommes allé(e)s'], ['vous', 'avez parlé', 'êtes allé(e)(s)'], ['ils / elles', 'ont parlé', 'sont allés / allées']],
      ex: [['Hier, j’ai vu un bon film.', 'Gisteren zag ik een goede film.'], ['Elle est née en 1990.', 'Ze is in 1990 geboren.'], ['On a mangé puis on est sortis.', 'We aten en gingen toen uit.']],
      uz: [['Geen "hier, je mangeais" voor één gebeurtenis', 'Nederlanders kiezen bij "gisteren at ik" snel de imparfait, omdat die op onze verleden tijd lijkt. Toch is het <i>j’ai mangé</i>. <b>Waarom?</b> In het Frans bepaalt niet de vorm maar de <b>blik</b> de keuze: een afgeronde gebeurtenis is altijd passé composé; de imparfait is voor achtergrond en gewoonte.']] },
    imperfecto: { n: 'l’imparfait', t: 'Imparfait', k: 'De verleden tijd voor achtergrond en gewoontes: quand j’étais petit, j’habitais à Lille.', a: ['imparfait'],
      gen: 'Ook een <b>verleden tijd</b>, maar voor de <b>achtergrond</b> van een verhaal, hoe iets was, en wat je vroeger <b>gewoonlijk</b> deed: <i>vroeger <b>woonde</b> ik in Lille</i>, <i>het <b>regende</b> en ik <b>was</b> moe</i>.',
      html: 'De <b>imparfait</b> maak je van de <b>nous-vorm</b> van de tegenwoordige tijd: <i>nous parl-ons → je parl<b>ais</b></i>. Uitgangen: <i>-ais, -ais, -ait, -ions, -iez, -aient</i>. Je gebruikt hem voor beschrijvingen, gewoontes en wat er <b>gaande was</b> toen iets anders gebeurde: <i>Je <b>dormais</b> quand tu as appelé</i>.',
      table: [['', 'parler', 'être'], ['je / j’', 'parlais', 'étais'], ['tu', 'parlais', 'étais'], ['il / elle / on', 'parlait', 'était'], ['nous', 'parlions', 'étions'], ['vous', 'parliez', 'étiez'], ['ils / elles', 'parlaient', 'étaient']],
      ex: [['Quand j’étais petit, j’habitais à Lille.', 'Toen ik klein was, woonde ik in Lille.'], ['Il pleuvait et il faisait froid.', 'Het regende en het was koud.'], ['Je lisais quand il est entré.', 'Ik was aan het lezen toen hij binnenkwam.']],
      uz: [['être: j’étais', '<i>être</i> is het <b>enige</b> werkwoord dat de imparfait niet van de nous-vorm maakt (<i>nous sommes</i> → geen <i>sommais</i>), maar van de stam <b>ét-</b>. <b>Waarom?</b> <i>sommes</i> komt van het Latijnse <i>sumus</i>, terwijl de imparfait teruggaat op een ander werkwoord, <i>stare</i> (staan), dat ook <i>été</i> opleverde.'],
        ['Si j’avais le temps …', 'Na <b>si</b> (als) staat de imparfait ook voor iets <b>denkbeeldigs nu</b>: <i>Si j’<b>avais</b> le temps, je voyagerais</i>. Nooit <i>si j’aurais</i>. <b>Waarom?</b> De verleden tijd schept afstand tot de werkelijkheid, precies zoals in het Nederlands: "als ik tijd <b>had</b>".']] },
    perfecto: { n: 'le passé composé · le plus-que-parfait', a: ['plus-que-parfait', 'futur antérieur'], k: 'Heb/is + deelwoord: ik heb gegeten, j’ai mangé.',
      html: 'De gewone voltooide tijd is de <b>passé composé</b> (zie daar): <i>j’ai mangé</i>. Daarnaast is er de <b>plus-que-parfait</b> voor wat al gebeurd wás: hulpwerkwoord in de imparfait + deelwoord: <i>j’<b>avais</b> mangé</i>, <i>elle <b>était</b> partie</i>. En de <b>futur antérieur</b> voor wat gebeurd zal zijn: <i>j’<b>aurai</b> fini</i>.',
      ex: [['J’ai déjà mangé.', 'Ik heb al gegeten.'], ['Quand je suis arrivé, elle était déjà partie.', 'Toen ik aankwam, was ze al weg.'], ['J’aurai fini à midi.', 'Ik zal om twaalf uur klaar zijn.']],
      uz: [['J’habite ici depuis deux ans.', '"Ik woon hier al twee jaar" is in het Frans <b>tegenwoordige tijd</b> met <i>depuis</i>, geen voltooide tijd: niet <i>j’ai habité ici depuis</i>. <b>Waarom?</b> Het is nog steeds zo; de passé composé zou betekenen dat het voorbij is.']] },
    futuro: { n: 'le futur', a: ['futur proche', 'futur simple', 'futur'], k: 'Wat later gebeurt: ik zal reizen, je vais voyager.',
      html: 'Twee vormen. De <b>futur proche</b> is <i>aller</i> + infinitief en is het gewoonst in spreektaal: <i>Je <b>vais partir</b></i>. De <b>futur simple</b> is infinitief + <i>-ai, -as, -a, -ons, -ez, -ont</i>: <i>je parler<b>ai</b></i>. Werkwoorden op -re verliezen de e: <i>prendre → je prendrai</i>.',
      table: [['', 'parler', 'onregelmatige stammen'], ['je', 'parlerai', 'être → ser- · avoir → aur-'], ['tu', 'parleras', 'aller → ir- · faire → fer-'], ['il / elle', 'parlera', 'venir → viendr- · voir → verr-'], ['nous', 'parlerons', 'pouvoir → pourr- · vouloir → voudr-'], ['vous', 'parlerez', 'devoir → devr- · savoir → saur-'], ['ils / elles', 'parleront', 'falloir → il faudra']],
      ex: [['Je vais appeler Léa.', 'Ik ga Léa bellen.'], ['Demain, il fera beau.', 'Morgen wordt het mooi weer.'], ['Quand je serai grand, je serai pilote.', 'Als ik groot ben, word ik piloot.']],
      uz: [['Quand tu viendras …', 'Na <i>quand</i> staat in het Frans de <b>futur</b> als het over de toekomst gaat: <i>Quand tu <b>viendras</b>, on mangera</i>. In het Nederlands staat daar de tegenwoordige tijd ("als je komt"). <b>Waarom?</b> Het Frans is hier logisch streng: het komen ligt nog in de toekomst, dus krijgt het de toekomende tijd. Na <i>si</i> juist niet: <i>si tu viens</i>.']] },
    condicional: { n: 'le conditionnel', a: ['conditionnel(?: présent| passé)?'], k: 'Zou + werkwoord: ik zou graag willen, je voudrais.',
      html: 'De <b>conditionnel</b> is de stam van de futur + de uitgangen van de imparfait: <i>je parler<b>ais</b></i>, <i>j’aur<b>ais</b></i>, <i>je voudr<b>ais</b></i>. Gebruik: beleefd vragen (<i>Je voudrais un café</i>), advies (<i>Tu devrais dormir</i>) en het denkbeeldige: <i>Si j’avais le temps, je <b>voyagerais</b></i>. De <b>conditionnel passé</b> (<i>j’aurais dû</i>) is voor spijt en verwijt.',
      ex: [['Je voudrais un café, s’il vous plaît.', 'Ik zou graag een koffie willen.'], ['Tu devrais te reposer.', 'Je zou moeten uitrusten.'], ['Si j’étais riche, j’achèterais une maison.', 'Als ik rijk was, zou ik een huis kopen.'], ['J’aurais dû t’appeler.', 'Ik had je moeten bellen.']],
      uz: [['Nooit si + conditionnel', 'Na <i>si</i> (als) komt nooit de conditionnel: <i>Si j’<b>avais</b> …, je <b>ferais</b> …</i>, niet <i>si j’aurais</i>. Franse kinderen leren: <i>les si n’aiment pas les -rais</i>. <b>Waarom?</b> De si-zin noemt de voorwaarde (verleden tijd voor afstand), alleen het gevolg krijgt "zou". Net als in het Nederlands: "als ik tijd <b>had</b>".']] },
    subjuntivo: { n: 'le subjonctif', t: 'Subjonctif (aanvoegende wijs)', k: 'De werkwoordsvorm na wens, gevoel, twijfel en noodzaak: il faut que tu viennes.', a: ['subjonctif'],
      html: 'De <b>subjonctif</b> staat bijna altijd na <b>que</b>, als de hoofdzin een wens, gevoel, twijfel of noodzaak uitdrukt: <i>Je veux que …, Je suis content que …, Je ne pense pas que …, Il faut que …</i> en na voegwoorden als <i>pour que, bien que, avant que</i>. Vorm: stam van de <b>ils-vorm</b> van de tegenwoordige tijd + <i>-e, -es, -e, -ions, -iez, -ent</i>: <i>ils vienn-ent → que je vienn<b>e</b></i>.',
      table: [['', 'parler', 'être', 'avoir', 'aller', 'faire'], ['que je / j’', 'parle', 'sois', 'aie', 'aille', 'fasse'], ['que tu', 'parles', 'sois', 'aies', 'ailles', 'fasses'], ['qu’il / elle', 'parle', 'soit', 'ait', 'aille', 'fasse'], ['que nous', 'parlions', 'soyons', 'ayons', 'allions', 'fassions'], ['que vous', 'parliez', 'soyez', 'ayez', 'alliez', 'fassiez'], ['qu’ils / elles', 'parlent', 'soient', 'aient', 'aillent', 'fassent']],
      ex: [['Il faut que tu viennes.', 'Je moet komen.'], ['Je suis content que tu sois là.', 'Ik ben blij dat je er bent.'], ['Bien qu’il pleuve, on sort.', 'Hoewel het regent, gaan we uit.'], ['Je veux partir.', 'Ik wil weggaan. (zelfde onderwerp: infinitief)']],
      uz: [['espérer que + indicatif', 'Na <i>j’espère que</i> volgt <b>geen</b> subjonctif: <i>J’espère que tu <b>viendras</b></i>, terwijl <i>Je souhaite que tu <b>viennes</b></i> hem wel krijgt. <b>Waarom?</b> Het Frans behandelt hopen als verwachten (je gaat ervan uit dat het gebeurt), en bij verwachting hoort de gewone wijs.'],
        ['Je pense que … / Je ne pense pas que …', 'Bevestigend: <i>Je pense qu’il <b>a</b> raison</i> (indicatif). Ontkennend: <i>Je ne pense pas qu’il <b>ait</b> raison</i> (subjonctif). <b>Waarom?</b> Wie iets denkt, stelt het als feit voor; wie het niet denkt, twijfelt eraan, en twijfel vraagt de subjonctif.']] },
    imperativo: { n: 'l’impératif', k: 'Een bevel, verzoek of advies: kom!, eet!, viens !',
      html: 'De gebiedende wijs heeft drie vormen, zonder onderwerp: <b>tu</b> (<i>Parle !</i>), <b>nous</b> (<i>Parlons !</i> = laten we praten) en <b>vous</b> (<i>Parlez !</i>). Ontkennend: <i><b>Ne</b> parle <b>pas</b> !</i> Voornaamwoorden komen er bij een bevestiging achter: <i>Écoute-<b>moi</b> !</i>, bij een ontkenning ervoor: <i>Ne <b>me</b> regarde pas !</i>',
      ex: [['Attends !', 'Wacht!'], ['Allons-y !', 'Laten we gaan!'], ['Asseyez-vous.', 'Gaat u zitten.'], ['Ne t’inquiète pas.', 'Maak je geen zorgen.']],
      uz: [['Parle ! zonder -s', 'Werkwoorden op <b>-er</b> (en <i>aller</i>) verliezen bij <i>tu</i> de <b>-s</b>: <i>tu parles → Parle !</i>, <i>tu vas → Va !</i> Maar: <i>Vas-y !</i>, <i>Parles-en !</i> <b>Waarom?</b> De Latijnse gebiedende wijs had daar nooit een s; vóór <i>y</i> en <i>en</i> komt hij terug om twee botsende klinkers te vermijden.'],
        ['Sois, aie, sache, veuillez', '<i>être, avoir, savoir</i> en <i>vouloir</i> nemen hun vormen uit de subjonctif: <i>Sois sage !</i>, <i>N’aie pas peur !</i>, <i>Sachez que …</i>, <i>Veuillez patienter.</i> <b>Waarom?</b> Je kunt iemand niet echt bevelen iets te zijn, te hebben of te weten; het is eerder een wens, en daar hoort de subjonctif bij.']] },
    geslacht: { n: 'le genre',
      html: 'Twee geslachten: <b>mannelijk</b> (<i>le, un</i>) en <b>vrouwelijk</b> (<i>la, une</i>). Het geslacht bepaalt de vorm van lidwoord, bijvoeglijk naamwoord, bezittelijk voornaamwoord en soms het deelwoord. Vrouwelijke vormen van beroepen en personen: vaak <b>+e</b> (<i>étudiant, étudiante</i>), <i>-eur → -euse</i> (<i>vendeur, vendeuse</i>), <i>-teur → -trice</i> (<i>acteur, actrice</i>), <i>-ien → -ienne</i>.',
      ex: [['un étudiant, une étudiante', 'een student, een studente'], ['le soleil, la lune', 'de zon, de maan'], ['un acteur, une actrice', 'een acteur, een actrice']],
      uz: [['le musée, le lycée, le silence', 'Woorden op <b>-ée</b> en <b>-ence</b> zijn vrouwelijk (<i>une idée, la différence</i>), maar <i>le musée, le lycée, le silence</i> zijn mannelijk. <b>Waarom?</b> Ze komen van onzijdige Griekse en Latijnse woorden (<i>museum, lyceum, silentium</i>), en onzijdig werd in het Frans mannelijk.'],
        ['une personne, une victime, une star', 'Deze woorden zijn <b>altijd vrouwelijk</b>, ook als het om een man gaat: <i>Paul est une personne sympathique</i>. <b>Waarom?</b> Het geslacht hoort bij het woord, niet bij de persoon die je ermee aanduidt.']] },
    getal: { n: 'le singulier et le pluriel',
      html: 'Het meervoud krijgt meestal een <b>-s</b>, die je <b>niet hoort</b>: <i>le livre, les livres</i>. Je hoort het meervoud aan het lidwoord (<i>le → les</i>). Woorden op <i>-s, -x, -z</i> veranderen niet (<i>un bus, des bus</i>); woorden op <i>-eau, -eu</i> krijgen <b>-x</b> (<i>des bateaux</i>); woorden op <i>-al</i> worden <b>-aux</b> (<i>un journal, des journaux</i>).',
      ex: [['un livre, des livres', 'een boek, boeken'], ['un gâteau, des gâteaux', 'een taart, taarten'], ['un cheval, des chevaux', 'een paard, paarden']],
      uz: [['un œil, des yeux', '<i>œil</i> (oog) heeft het meervoud <b>yeux</b>; ook <i>monsieur → messieurs</i>, <i>madame → mesdames</i>. <b>Waarom?</b> <i>yeux</i> is de klankwettige voortzetting van het oude meervoud (<i>ieuz</i>); bij <i>monsieur</i> zit er een bezittelijk voornaamwoord in (<i>mon sieur → mes sieurs</i>).'],
        ['des festivals, des bals', 'Een paar woorden op -al krijgen gewoon <b>-s</b>: <i>festivals, bals, carnavals</i>. <b>Waarom?</b> Het zijn late leenwoorden; -aux ontstond door een klankverandering in de middeleeuwen, en die was al voorbij toen deze woorden in het Frans kwamen.']] },
    congruentie: { n: 'l’accord',
      html: 'In het Frans moet veel <b>overeenkomen</b> met het zelfstandig naamwoord: lidwoord, bijvoeglijk naamwoord, bezittelijk voornaamwoord, en het deelwoord na <i>être</i>. Veel daarvan schrijf je wel maar hoor je niet: <i>Les petit<b>es</b> fill<b>es</b> sont arrivé<b>es</b></i>.',
      ex: [['un petit garçon, une petite fille', 'een kleine jongen, een klein meisje'], ['Mes amies sont parties.', 'Mijn vriendinnen zijn vertrokken.'], ['Ils sont contents.', 'Ze zijn tevreden.']],
      uz: [['des chaussures marron, des pulls orange', 'Kleuren die eigenlijk een <b>ding</b> zijn (<i>marron</i> = kastanje, <i>orange</i> = sinaasappel) veranderen niet. <b>Waarom?</b> Het zijn zelfstandige naamwoorden die als kleur worden gebruikt: "schoenen (in de kleur van een) kastanje".']] },
    verkleinwoord: { n: 'le diminutif', k: 'Iets kleiner of liever maken: huisje, une maisonnette.',
      html: 'Het Frans maakt veel <b>minder</b> verkleinwoorden dan het Nederlands. Meestal zeg je gewoon <b>petit</b>: <i>un petit café</i> (een kopje koffie, een koffietje). De uitgang <b>-ette</b> (soms <i>-et</i>) bestaat wel, maar zit vooral in vaste woorden: <i>une maisonnette, une fillette, un jardinet</i>.',
      ex: [['un petit moment', 'een momentje'], ['une petite maison', 'een huisje'], ['une fourchette', 'een vork (letterlijk: klein vorkje)']] },
    vergelijking: { n: 'la comparaison', gen: 'Met de <b>vergrotende trap</b> vergelijk je twee dingen (<i>Parijs is <b>groter</b> dan Lyon</i>). Met de <b>overtreffende trap</b> zeg je dat iets het meest is (<i>de <b>grootste</b> stad</i>).',
      html: 'Vergelijken doe je met <b>plus … que</b> (meer), <b>moins … que</b> (minder) en <b>aussi … que</b> (even). De overtreffende trap krijgt het lidwoord erbij: <i><b>le plus</b> grand</i>, <i><b>la moins</b> chère</i>.',
      ex: [['Lyon est plus petit que Paris.', 'Lyon is kleiner dan Parijs.'], ['Il est aussi grand que moi.', 'Hij is even groot als ik.'], ['C’est le meilleur restaurant de la ville.', 'Dat is het beste restaurant van de stad.']],
      uz: [['meilleur en mieux', '"Beter" is <b>meilleur</b> bij een zelfstandig naamwoord (van <i>bon</i>) en <b>mieux</b> bij een werkwoord (van <i>bien</i>): <i>un <b>meilleur</b> film</i>, <i>elle chante <b>mieux</b></i>. Nooit <i>plus bon</i>. <b>Waarom?</b> Het zijn de oude Latijnse vormen (<i>melior, melius</i>) die door hun hoge frequentie nooit door <i>plus</i> + woord zijn vervangen.']] },
    accent: { n: 'les accents', k: 'De tekens op Franse letters (é, è, ê, ç, ë) en wat ze met de uitspraak doen.',
      gen: 'Een <b>accent</b> is een teken op of onder een letter dat iets over de uitspraak of betekenis zegt. De <b>klemtoon</b> is de lettergreep die je het hardst zegt: <i>ta<b>FEL</b></i>, <i><b>AU</b>to</i>.',
      html: 'In het Frans ligt de klemtoon altijd op de <b>laatste</b> lettergreep van een woordgroep; daar hoef je dus niets voor te leren. De accenten doen iets anders: <b>é</b> (accent aigu) klinkt als de ee in "zee"; <b>è</b> en <b>ê</b> (grave, circonflexe) klinken als de e in "pet"; <b>ç</b> (cedille) klinkt als s; het <b>trema</b> (ë, ï) zegt dat je de klinker los uitspreekt: <i>Noël</i>.',
      ex: [['le café, l’été', 'de koffie, de zomer'], ['la mère, le père', 'de moeder, de vader'], ['le garçon, ça', 'de jongen, dat'], ['où (waar) · ou (of)', 'het accent onderscheidt twee woorden']],
      uz: [['forêt, hôpital, fête', 'De <b>circonflexe</b> (^) staat vaak waar vroeger een <b>s</b> stond: <i>forêt</i> (forest), <i>hôpital</i> (hospitaal), <i>fête</i> (feest), <i>île</i> (eiland, Engels isle). <b>Waarom?</b> Die s werd in de middeleeuwen niet meer uitgesproken; het dakje is het aandenken, en helpt je de betekenis te raden.']] },
    aanspreken: { n: 'tu et vous', t: 'Tu en vous', k: 'Jij of u zeggen: tutoyer en vouvoyer.', a: ['tutoyer', 'vouvoyer', 'tutoiement', 'vouvoiement'],
      html: 'Frans is <b>formeler</b> dan Nederlands. <b>Vous</b> zeg je tegen onbekenden, in winkels, tegen oudere mensen en vaak op het werk; <b>tu</b> tegen familie, vrienden, kinderen en leeftijdgenoten onder elkaar. Bij twijfel: begin met <i>vous</i> en wacht tot de ander voorstelt: <i>On peut se tutoyer ?</i> <i>Vous</i> is ook altijd het meervoud ("jullie").',
      ex: [['Tu vas bien ?', 'Gaat het goed met je?'], ['Vous allez bien ?', 'Gaat het goed met u / met jullie?'], ['On peut se tutoyer ?', 'Zullen we je en jij zeggen?']],
      uz: [['Vous êtes prête, madame ?', 'Bij beleefd <i>vous</i> tegen <b>één</b> persoon staat het werkwoord in het meervoud, maar het bijvoeglijk naamwoord in het <b>enkelvoud</b>: <i>Vous êtes prêt<b>e</b></i>, niet <i>prêtes</i>. <b>Waarom?</b> Het werkwoord volgt de vorm (<i>vous</i>), het bijvoeglijk naamwoord volgt de werkelijkheid: één persoon.'],
        ['Québec 🇨🇦 zegt sneller tu', 'In Québec zegt men veel sneller <i>tu</i>, ook tegen onbekenden en in winkels. <b>Waarom?</b> De omgangsvormen zijn er Noord-Amerikaans informeel; <i>vous</i> houdt men voor ouderen en heel formele situaties.']] }
  });
})(window.SPT);
